.libPaths(c('/Volumes/Brain6Work/cfdr-order-empty-lib','/Volumes/Brain6Work/lib','/Volumes/Extreme SSD/brain6-work/exploratory-finemap-coloc-v1/Rlib',.libPaths()))
library(cfdr.pleio);library(data.table);library(Matrix)
args<-commandArgs(trailingOnly=TRUE);stopifnot(length(args)==1,!dir.exists(args[1]));dir.create(args[1]);refdir<-file.path(args[1],'ref');dir.create(refdir)
set.seed(777);n<-66;x<-data.table(SNP=sample(sprintf('s%03d',1:n)),CHR=rep(1:22,each=3),BP=rep(c(100,200,300),22),A1='A',A2='C',MAF=.2,INTERGENIC=1L);trait<-data.table(SNP=x$SNP,BETA=seq_len(n)/100,PVAL=seq_len(n)/(n+1));trait<-rbind(trait,data.table(SNP='unmatched',BETA=.1,PVAL=.5));saveRDS(x[sample(.N)],file.path(refdir,'all_chr_perVariant.rds'))
for(chr in 1:22){ids<-x[CHR==chr,SNP];m<-as(Matrix(matrix(c(0,0,0,0,0,1,0,1,0),3),sparse=TRUE),'generalMatrix');dimnames(m)<-list(ids,ids);stopifnot(inherits(m,'dgCMatrix'),length(which_col(m,1))==0,identical(which_col(m,2),3L),identical(which_col(m,3),2L));saveRDS(m,file.path(refdir,sprintf('chr%02d_LDpairs.rds',chr)))}
expected<-x[order(CHR,BP,SNP),SNP];result<-list()
for(k in 1:3){d<-file.path(args[1],paste0('run',k));v<-trait[sample(.N)];obj<-cfdr_pleio$new();obj$init_data(v,v,refdat=refdata_location(refdir),local_refdat_path=d,verbose=FALSE);tab<-readRDS(get_variants(obj$refdat_local));mids<-unlist(lapply(1:22,function(i)colnames(readRDS(get_chrmat(obj$refdat_local,i)))),use.names=FALSE);stopifnot(identical(tab$SNP,expected),identical(obj$trait_data$SNP,expected),identical(mids,expected),!('unmatched' %in% expected));stopifnot(all.equal(obj$trait_data$BETA1,trait$BETA[match(expected,trait$SNP)]));obj$initialize_pruning_index(n_iter=10,seed=1234,verbose=FALSE);for(i in 1:22){indices<-(3*i-2):(3*i);stopifnot(all(obj$index[indices[1],]),all(colSums(obj$index[indices[2:3],,drop=FALSE])==1))};result[[k]]<-obj$index}
stopifnot(identical(result[[1]],result[[2]]),identical(result[[1]],result[[3]]));cat('PASS: 66 SNPs across 22 chromosomes, one unmatched input SNP, three permutations, ten fixed-seed pruning iterations; isolated SNPs retained and exactly one in every linked pair retained.\n');print(sessionInfo())
